// src/components/MapView.js
import React from 'react';
import '../styles/MapView.css';

function MapView() {
  return (
    <div className="map-view">
      <button className="map-button">Добавить событие на карту</button>
      <button className="map-button">Поиск событий</button>
      <button className="filter-button">
        <span role="img" aria-label="filter">🔍</span> Фильтр
      </button>
      <div className="map-container">
        {/* Тут будет отображение карты */}
      </div>
    </div>
  );
}

export default MapView;
